param(
    [string]$ProjectRoot = "E:\MY PROJECT FOLDER\AURA PROJECT\AURA-Butler-Android-Studio-v0.4.0-Native-Stable",
    [string]$CloudRoot = "E:\MY PROJECT FOLDER\AURA CLOUD",
    [switch]$SkipBuild,
    [switch]$Install,
    [switch]$DeviceQA,
    [switch]$DeployCloud,
    [int]$CloudWarmSeconds = 0,
    [string]$JavaHome = "",
    [switch]$KeepLegacyCloudSources
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Section([string]$Text) {
    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Cyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host "============================================================" -ForegroundColor Cyan
}
function Pass([string]$Text) { Write-Host ("PASS: " + $Text) -ForegroundColor Green }
function Warn([string]$Text) { Write-Host ("WARN: " + $Text) -ForegroundColor Yellow }
function Assert-Gate {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][bool]$Condition
    )
    if (-not $Condition) {
        throw "Static gate failed: $Name"
    }
    Pass $Name
}

function Get-Sha([string]$Path) {
    (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
}
function Write-B64([string]$Path, [string]$Payload) {
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent -PathType Container)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }
    [IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Payload))
}
function Add-JavaCandidate {
    param(
        [System.Collections.Generic.List[string]]$List,
        [string]$Candidate
    )
    if (-not [string]::IsNullOrWhiteSpace($Candidate)) {
        [void]$List.Add($Candidate)
    }
}

function Resolve-JavaHomeCandidate {
    param([string]$Candidate)
    if ([string]::IsNullOrWhiteSpace($Candidate)) { return $null }

    $clean = [Environment]::ExpandEnvironmentVariables($Candidate.Trim())
    $clean = $clean.Trim([char]34)

    $javaExe = Join-Path $clean "bin\java.exe"
    if (Test-Path -LiteralPath $javaExe -PathType Leaf) {
        try {
            return (Resolve-Path -LiteralPath $clean).Path
        } catch {
            return $clean
        }
    }
    return $null
}

function Find-JavaHome {
    param([string]$PreferredJavaHome)

    $candidates = New-Object System.Collections.Generic.List[string]

    Add-JavaCandidate $candidates $PreferredJavaHome
    Add-JavaCandidate $candidates $env:STUDIO_JDK
    Add-JavaCandidate $candidates $env:JDK_HOME
    Add-JavaCandidate $candidates $env:JAVA_HOME

    $javaCommand = Get-Command java.exe -ErrorAction SilentlyContinue
    if (-not $javaCommand) {
        $javaCommand = Get-Command java -ErrorAction SilentlyContinue
    }
    if ($javaCommand -and $javaCommand.Source) {
        $javaBin = Split-Path -Parent $javaCommand.Source
        Add-JavaCandidate $candidates (Split-Path -Parent $javaBin)
    }

    foreach ($processName in @("studio64", "studio")) {
        foreach ($process in @(Get-Process -Name $processName -ErrorAction SilentlyContinue)) {
            try {
                if ($process.Path) {
                    $studioRoot = Split-Path -Parent $process.Path
                    Add-JavaCandidate $candidates (Join-Path $studioRoot "jbr")
                    Add-JavaCandidate $candidates (Join-Path $studioRoot "jre")
                }
            } catch {
            }
        }
    }

    foreach ($envRoot in @(
        $env:ProgramW6432,
        $env:ProgramFiles,
        ${env:ProgramFiles(x86)},
        $env:LOCALAPPDATA
    )) {
        if (-not [string]::IsNullOrWhiteSpace($envRoot)) {
            Add-JavaCandidate $candidates (Join-Path $envRoot "Android\Android Studio\jbr")
            Add-JavaCandidate $candidates (Join-Path $envRoot "Android\Android Studio\jre")
            Add-JavaCandidate $candidates (Join-Path $envRoot "Programs\Android Studio\jbr")
            Add-JavaCandidate $candidates (Join-Path $envRoot "Google\AndroidStudio\jbr")
        }
    }

    foreach ($registryPattern in @(
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )) {
        foreach ($entry in @(Get-ItemProperty $registryPattern -ErrorAction SilentlyContinue)) {
            try {
                if ($entry.DisplayName -and ([string]$entry.DisplayName -like "*Android Studio*")) {
                    if ($entry.InstallLocation) {
                        Add-JavaCandidate $candidates (Join-Path ([string]$entry.InstallLocation) "jbr")
                        Add-JavaCandidate $candidates (Join-Path ([string]$entry.InstallLocation) "jre")
                    }
                }
            } catch {
            }
        }
    }

    foreach ($drive in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)) {
        foreach ($relative in @(
            "Program Files\Android\Android Studio\jbr",
            "Program Files\Android\Android Studio\jre",
            "Program Files (x86)\Android\Android Studio\jbr",
            "Program Files (x86)\Android\Android Studio\jre",
            "Android\Android Studio\jbr",
            "Android\Android Studio\jre",
            "Android Studio\jbr",
            "Android Studio\jre"
        )) {
            try {
                Add-JavaCandidate $candidates (Join-Path $drive.Root $relative)
            } catch {
            }
        }
    }

    foreach ($candidate in @($candidates | Select-Object -Unique)) {
        $resolved = Resolve-JavaHomeCandidate $candidate
        if ($resolved) { return $resolved }
    }

    return $null
}
function Find-Adb {
    $candidates = New-Object System.Collections.Generic.List[string]
    [void]$candidates.Add("E:\AndroidSDK\platform-tools\adb.exe")
    if ($env:ANDROID_SDK_ROOT) { [void]$candidates.Add((Join-Path $env:ANDROID_SDK_ROOT "platform-tools\adb.exe")) }
    if ($env:ANDROID_HOME) { [void]$candidates.Add((Join-Path $env:ANDROID_HOME "platform-tools\adb.exe")) }
    if ($env:LOCALAPPDATA) { [void]$candidates.Add((Join-Path $env:LOCALAPPDATA "Android\Sdk\platform-tools\adb.exe")) }
    foreach ($candidate in ($candidates | Select-Object -Unique)) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $candidate }
    }
    $cmd = Get-Command adb.exe -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    return $null
}
function Find-Python {
    foreach ($candidate in @(
        (Join-Path $CloudRoot ".venv\Scripts\python.exe"),
        (Join-Path $CloudRoot "venv\Scripts\python.exe")
    )) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
    }
    $cmd = Get-Command python.exe -ErrorAction SilentlyContinue
    if (-not $cmd) { $cmd = Get-Command python -ErrorAction SilentlyContinue }
    if ($cmd) { return $cmd.Source }
    return $null
}
function Find-Modal {
    foreach ($candidate in @(
        (Join-Path $CloudRoot ".venv\Scripts\modal.exe"),
        (Join-Path $CloudRoot "venv\Scripts\modal.exe")
    )) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
    }
    $cmd = Get-Command modal.exe -ErrorAction SilentlyContinue
    if (-not $cmd) { $cmd = Get-Command modal -ErrorAction SilentlyContinue }
    if ($cmd) { return $cmd.Source }
    return $null
}
function Restore-All {
    param([string]$BackupRoot, [hashtable]$PreUpgradePresence, [bool]$RestoreCloudConfig)
    Warn "Restoring the exact pre-upgrade source from backup..."
    foreach ($relative in $PreUpgradePresence.Keys) {
        $target = Join-Path $ProjectRoot $relative
        $backup = Join-Path $BackupRoot ("android-source\" + $relative)
        if ([bool]$PreUpgradePresence[$relative]) {
            if (Test-Path -LiteralPath $backup -PathType Leaf) {
                $parent = Split-Path -Parent $target
                if ($parent -and -not (Test-Path -LiteralPath $parent -PathType Container)) {
                    New-Item -ItemType Directory -Path $parent -Force | Out-Null
                }
                Copy-Item -LiteralPath $backup -Destination $target -Force
            }
        } else {
            Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
        }
    }
    $cloudBackup = Join-Path $BackupRoot "cloud\aura_models.py"
    if (Test-Path -LiteralPath $cloudBackup -PathType Leaf) {
        Copy-Item -LiteralPath $cloudBackup -Destination (Join-Path $CloudRoot "aura_models.py") -Force
    }
    if ($RestoreCloudConfig) {
        $configBackup = Join-Path $BackupRoot "cloud\aura_student_config.py"
        if (Test-Path -LiteralPath $configBackup -PathType Leaf) {
            Copy-Item -LiteralPath $configBackup -Destination (Join-Path $CloudRoot "aura_student_config.py") -Force
        }
    }
    Pass "Pre-upgrade source restored."
}

