$CloudAllowedHashes = @("C2F0893345050048AB37DBD9957812E970CBA59DCCEAB098B6B7C77DF23BB679", "17D4C32D1D842EE416AD41C20ED87A57C174CB0B34C0D12F26B8F666C4715CBD")
$CloudFinalHash = "17D4C32D1D842EE416AD41C20ED87A57C174CB0B34C0D12F26B8F666C4715CBD"
$CloudPayload = ""
$VoiceGuardOriginalHash = "86C4AA6669979C6631D2C3343DC3108E2FBFE9179085EB6BBAC76B11040013D8"

$AuditTextBase64 = ""
$AuditText = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($AuditTextBase64))

Section "AURA v0.17.2 Reliability + Latency - Installer r9"
Write-Host "Android: $ProjectRoot"
Write-Host "Cloud:   $CloudRoot"
Write-Host ""
Write-Host "Combined voice + reliability + latency + privacy + budget + UX repair. Installer revision r9." -ForegroundColor Cyan
Write-Host "No Ollama installation. No giant laptop LLM download." -ForegroundColor Green
Pass "Installer r9 loaded"

if (-not (Test-Path -LiteralPath $ProjectRoot -PathType Container)) { throw "Project root not found: $ProjectRoot" }
if (-not (Test-Path -LiteralPath $CloudRoot -PathType Container)) { throw "Cloud root not found: $CloudRoot" }
if ($CloudWarmSeconds -ne 0 -and ($CloudWarmSeconds -lt 30 -or $CloudWarmSeconds -gt 300)) {
    throw "-CloudWarmSeconds must be 0 or 30..300."
}
if ($SkipBuild -and ($Install -or $DeviceQA)) {
    throw "-SkipBuild cannot be combined with -Install or -DeviceQA."
}

$ResolvedJavaHome = $null
if (-not $SkipBuild) {
    Section "0/9 Java/JDK environment preflight"
    $ResolvedJavaHome = Find-JavaHome -PreferredJavaHome $JavaHome
    if (-not $ResolvedJavaHome) {
        throw @"
Java/JDK was not found. AURA source has NOT been modified.

Android Gradle requires Java before the build can start.
Android Studio normally includes its own JBR.

If Android Studio is installed in a custom location, rerun with:
  -JavaHome "FULL_PATH_TO_ANDROID_STUDIO_JBR"

Example:
  -JavaHome "C:\Program Files\Android\Android Studio\jbr"
"@
    }

    $env:JAVA_HOME = $ResolvedJavaHome
    $env:PATH = (Join-Path $ResolvedJavaHome "bin") + ";" + $env:PATH
    $javaExe = Join-Path $ResolvedJavaHome "bin\java.exe"
    Write-Host "JAVA_HOME: $ResolvedJavaHome"

    & $javaExe -version
    if ($LASTEXITCODE -ne 0) {
        throw "Detected Java could not execute successfully. AURA source has NOT been modified."
    }
    Pass "Java/JDK preflight"
}

$VoiceUpgradeNeeded = $false
$voiceGuardPath = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\voice\OwnerVoiceGuard.kt"
if (Test-Path -LiteralPath $voiceGuardPath -PathType Leaf) {
    $VoiceUpgradeNeeded = ((Get-Sha $voiceGuardPath) -eq $VoiceGuardOriginalHash)
}

Section "1/9 Baseline-aware preflight"
$PreUpgradePresence = @{}
foreach ($relative in $AndroidManifest.Keys) {
    $path = Join-Path $ProjectRoot $relative
    $info = $AndroidManifest[$relative]
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        if ([bool]$info.OriginalPresent) { throw "Required source file is missing: $relative" }
        $PreUpgradePresence[$relative] = $false
        Write-Host "NEW:  $relative"
        continue
    }
    $PreUpgradePresence[$relative] = $true
    $actual = Get-Sha $path
    if ($actual -notin @($info.Allowed)) {
        throw "Unexpected source drift: $relative`nActual SHA256: $actual`nNo v0.17.2 changes were made. Do not bypass the guard."
    }
    Pass $relative
}

$cloudPath = Join-Path $CloudRoot "aura_models.py"
if (-not (Test-Path -LiteralPath $cloudPath -PathType Leaf)) { throw "Missing canonical cloud source: $cloudPath" }
$cloudActual = Get-Sha $cloudPath
if ($cloudActual -notin $CloudAllowedHashes) {
    throw "Unexpected cloud source drift.`nActual SHA256: $cloudActual`nNo v0.17.2 changes were made."
}
Pass "Cloud canonical aura_models.py"

$configPath = Join-Path $CloudRoot "aura_student_config.py"
if ($CloudWarmSeconds -ne 0 -and -not (Test-Path -LiteralPath $configPath -PathType Leaf)) {
    throw "Cloud student config is missing: $configPath"
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot (".aura-v0.17.2-backup\" + $stamp)

Section "2/9 Timestamped backup"
foreach ($relative in $AndroidManifest.Keys) {
    $source = Join-Path $ProjectRoot $relative
    if (Test-Path -LiteralPath $source -PathType Leaf) {
        $dest = Join-Path $BackupRoot ("android-source\" + $relative)
        $parent = Split-Path -Parent $dest
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
        Copy-Item -LiteralPath $source -Destination $dest -Force
    }
}
New-Item -ItemType Directory -Path (Join-Path $BackupRoot "cloud") -Force | Out-Null
Copy-Item -LiteralPath $cloudPath -Destination (Join-Path $BackupRoot "cloud\aura_models.py") -Force
if ($CloudWarmSeconds -ne 0) {
    Copy-Item -LiteralPath $configPath -Destination (Join-Path $BackupRoot "cloud\aura_student_config.py") -Force
}
Pass "Backup: $BackupRoot"

$SourcePatched = $false
$ExternalSideEffectsStarted = $false
$DeviceQaWarning = $null
$finalDebugApk = Join-Path $ProjectRoot "AURA-v0.17.2-reliability-latency-debug.apk"

try {
    Section "3/9 Apply exact v0.17.2 source"
    foreach ($relative in $AndroidPayloads.Keys) {
        $target = Join-Path $ProjectRoot $relative
        Write-B64 $target $AndroidPayloads[$relative]
        $expected = [string]$AndroidManifest[$relative].Final
        if ((Get-Sha $target) -ne $expected) { throw "Post-write SHA256 mismatch: $relative" }
        Write-Host "PATCHED: $relative" -ForegroundColor Green
    }
    Write-B64 $cloudPath $CloudPayload
    if ((Get-Sha $cloudPath) -ne $CloudFinalHash) { throw "Post-write SHA256 mismatch: aura_models.py" }
    Write-Host "PATCHED: cloud\aura_models.py" -ForegroundColor Green

    if ($CloudWarmSeconds -ne 0) {
        $config = [IO.File]::ReadAllText($configPath)
        if ($config -notmatch "GPU_WARM_SECONDS\s*=\s*\d+") { throw "GPU_WARM_SECONDS marker not found." }
        $config = [regex]::Replace($config, "GPU_WARM_SECONDS\s*=\s*\d+", ("GPU_WARM_SECONDS = " + $CloudWarmSeconds), 1)
        [IO.File]::WriteAllText($configPath, $config, (New-Object Text.UTF8Encoding($false)))
        Write-Host "PATCHED: GPU_WARM_SECONDS = $CloudWarmSeconds" -ForegroundColor Yellow
    }

    $auditPath = Join-Path $ProjectRoot "AURA-v0.17.2-RELIABILITY-LATENCY-AUDIT.md"
    [IO.File]::WriteAllText($auditPath, $AuditText, (New-Object Text.UTF8Encoding($false)))
    $SourcePatched = $true

    Section "4/9 Static engineering gates"
    $gradleText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\build.gradle.kts"))
    $proguardText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\proguard-rules.pro"))
    $wakeText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\background\WakeWordService.kt"))
    $ownerText = [IO.File]::ReadAllText($voiceGuardPath)
    $keywordText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\assets\voice\kws\aura_keywords.txt"))
    $modelsText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\model\Models.kt"))
    $budgetText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\runtime\StudentBudgetPolicy.kt"))
    $hybridText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\data\HybridAiProvider.kt"))
    $productionText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\domain\ProductionButlerEngine.kt"))
    $newsText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\domain\NewsCommandEngine.kt"))
    $uiText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\ui\AuraApp.kt"))
    $sentinelText = [IO.File]::ReadAllText((Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\analyzer\ImportantMessageSentinel.kt"))
    $cloudText = [IO.File]::ReadAllText($cloudPath)

    Assert-Gate -Name "versionName" -Condition ($gradleText.Contains("0.17.2-reliability-latency"))
    Assert-Gate -Name "versionCode 27" -Condition ($gradleText.Contains("versionCode = 27"))
    Assert-Gate -Name "release minification remains enabled" -Condition (
        $gradleText.Contains("isMinifyEnabled = true") -and
        $gradleText.Contains("isShrinkResources = true")
    )

    $r8AnnotationRulesOk = (
        $proguardText.Contains("-dontwarn com.google.errorprone.annotations.CanIgnoreReturnValue") -and
        $proguardText.Contains("-dontwarn com.google.errorprone.annotations.CheckReturnValue") -and
        $proguardText.Contains("-dontwarn com.google.errorprone.annotations.Immutable") -and
        $proguardText.Contains("-dontwarn com.google.errorprone.annotations.RestrictedApi") -and
        $proguardText.Contains("-dontwarn javax.annotation.Nullable") -and
        $proguardText.Contains("-dontwarn javax.annotation.concurrent.GuardedBy") -and
        (-not $proguardText.Contains("-dontwarn **"))
    )
    Assert-Gate -Name "targeted Tink R8 annotation rules" -Condition $r8AnnotationRulesOk
    Assert-Gate -Name "FGS handshake fix" -Condition ($wakeText.Contains("completeForegroundHandshakeAndStop"))
    Assert-Gate -Name "owner profile schema v2" -Condition ($ownerText.Contains("PROFILE_SCHEMA_VERSION = 2"))
    Assert-Gate -Name "five owner enrollment samples" -Condition ($ownerText.Contains("ENROLLMENT_SAMPLES = 5"))
    Assert-Gate -Name "owner threshold floor 0.60" -Condition ($ownerText.Contains("DEFAULT_THRESHOLD = 0.60f"))
    Assert-Gate -Name "risky OR-A removed" -Condition (-not $keywordText.Contains("OR A"))
    Assert-Gate -Name "public fallback default OFF" -Condition ($modelsText.Contains("allowPublicAiFallback: Boolean = false"))

    $budgetReservationOk = (
        $budgetText.Contains("data class BudgetLease") -and
        $budgetText.Contains("fun tryReserve")
    )
    Assert-Gate -Name "budget reservation flow" -Condition $budgetReservationOk
    Assert-Gate -Name "quota messages are phone-native" -Condition (
        $budgetText.Contains("remain available directly on the phone") -and
        (-not $budgetText.Contains("remain available without a laptop"))
    )

    Assert-Gate -Name "private-Qwen-first router" -Condition ($hybridText.Contains("Private-Qwen-first optional AI router"))

    $turnDeadlineOk = (
        $productionText.Contains("totalTurnDeadlineMs") -and
        $productionText.Contains("remainingTurnMs")
    )
    Assert-Gate -Name "total turn deadline" -Condition $turnDeadlineOk

    $latencyMetricsOk = (
        $productionText.Contains("deterministic_ms") -and
        $productionText.Contains("delegated_ai_ms")
    )
    Assert-Gate -Name "stage latency metrics" -Condition $latencyMetricsOk

    $cachedHeadlinePathOk = (
        $newsText.Contains("AURA CACHED NEWS FOLLOW-UP") -and
        $newsText.Contains("qwen-cached-news-detail") -and
        $newsText.Contains("does not consume the scarce Deep Research allowance")
    )
    Assert-Gate -Name "cached headline path" -Condition $cachedHeadlinePathOk
    Assert-Gate -Name "streaming scroll bucket" -Condition ($uiText.Contains("streamingScrollBucket"))

    $boundedAlertQueueOk = (
        $sentinelText.Contains("ALERT_TTL_MS") -and
        $sentinelText.Contains("MAX_QUEUE_SIZE")
    )
    Assert-Gate -Name "bounded alert queue" -Condition $boundedAlertQueueOk

    Assert-Gate -Name "cloud release marker" -Condition ($cloudText.Contains("reliability-latency-v0.17.2"))
    Assert-Gate -Name "pinned torch" -Condition ($cloudText.Contains("torch==2.13.0"))
    Assert-Gate -Name "pinned transformers" -Condition ($cloudText.Contains("transformers==4.57.6"))
    Assert-Gate -Name "cloud budget lock" -Condition ($cloudText.Contains("skip_if_exists=True"))

    $activeText = Get-ChildItem -LiteralPath (Join-Path $ProjectRoot "android\app\src\main") -Recurse -File |
        Where-Object { $_.Extension -in @(".kt",".xml",".txt") } |
        ForEach-Object { [IO.File]::ReadAllText($_.FullName) }
    if (($activeText -join "`n") -match "(?i)laptop\s+Ollama") { throw "Stale laptop/Ollama user-facing text remains in Android active source." }
    if ($cloudText -match "(?i)laptop\s+Ollama") { throw "Stale laptop/Ollama user-facing text remains in cloud source." }
    Pass "No stale laptop/Ollama fallback text"

    Section "5/9 Cloud Python syntax"
    $python = Find-Python
    if (-not $python) { throw "Python not found for cloud syntax validation." }
    & $python -m py_compile $cloudPath
    if ($LASTEXITCODE -ne 0) { throw "Cloud Python syntax validation failed." }
    Pass "Cloud Python syntax"

    if (-not $SkipBuild) {
        Section "6/9 Android verification"
        $androidRoot = Join-Path $ProjectRoot "android"
        $gradlew = Join-Path $androidRoot "gradlew.bat"
        if (-not (Test-Path -LiteralPath $gradlew -PathType Leaf)) { throw "gradlew.bat not found." }

        if (-not $ResolvedJavaHome) {
            throw "Internal installer error: Java preflight result is missing."
        }
        $env:JAVA_HOME = $ResolvedJavaHome
        $env:PATH = (Join-Path $ResolvedJavaHome "bin") + ";" + $env:PATH
        Write-Host "JAVA_HOME: $ResolvedJavaHome"

        Push-Location $androidRoot
        try {
            & $gradlew --no-daemon testDebugUnitTest lintDebug assembleDebug assembleRelease assembleDebugAndroidTest
            if ($LASTEXITCODE -ne 0) { throw "Gradle verification failed with exit code $LASTEXITCODE." }
        } finally { Pop-Location }

        $debugApk = Join-Path $androidRoot "app\build\outputs\apk\debug\app-debug.apk"
        if (-not (Test-Path -LiteralPath $debugApk -PathType Leaf)) { throw "Debug APK not found after Gradle success." }
        Copy-Item -LiteralPath $debugApk -Destination $finalDebugApk -Force
        Pass "Debug APK: $finalDebugApk"

        $releaseDir = Join-Path $androidRoot "app\build\outputs\apk\release"
        $releaseApk = Get-ChildItem -LiteralPath $releaseDir -Filter "*.apk" -File -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($releaseApk) {
            $finalRelease = Join-Path $ProjectRoot "AURA-v0.17.2-reliability-latency-release-unsigned.apk"
            Copy-Item -LiteralPath $releaseApk.FullName -Destination $finalRelease -Force
            Pass "Release APK: $finalRelease"
        } else {
            Warn "assembleRelease returned success but no release APK was found to copy."
        }
        Pass "testDebugUnitTest + lintDebug + assembleDebug + assembleRelease + assembleDebugAndroidTest"
    } else {
        Section "6/9 Android build skipped"
        Warn "Gradle validation was intentionally skipped."
    }

    if ($DeployCloud) {
        Section "7/9 Deploy cloud"
        $modal = Find-Modal
        if (-not $modal) { throw "Modal CLI not found. Cloud source is patched but not deployed." }
        $ExternalSideEffectsStarted = $true
        Push-Location $CloudRoot
        try {
            & $modal deploy "aura_models.py"
            if ($LASTEXITCODE -ne 0) { throw "Modal deploy failed with exit code $LASTEXITCODE." }
        } finally { Pop-Location }
        Pass "Modal deployment completed."
        Write-Host "No Qwen/Gemma health request was forced, so the installer does not intentionally cold-start the GPU models." -ForegroundColor Green
    } else {
        Section "7/9 Cloud deploy skipped"
        Warn "Run with -DeployCloud to publish the patched cloud source."
    }

    if ($Install) {
        Section "8/9 Install Android update"
        $adb = Find-Adb
        if (-not $adb) { throw "adb.exe not found." }
        $ExternalSideEffectsStarted = $true
        & $adb start-server | Out-Host
        & $adb devices -l | Out-Host
        & $adb install -r $finalDebugApk | Out-Host
        if ($LASTEXITCODE -ne 0) { throw "ADB update install failed." }

        $pkg = @(& $adb shell dumpsys package in.diganta.aurabutler 2>&1)
        $pkg | Select-String -Pattern "versionName|versionCode" | Out-Host
        if (($pkg -join "`n") -notmatch "versionName=0\.17\.2-reliability-latency") {
            throw "Installed package did not report v0.17.2."
        }
        Pass "Android update installed; app data preserved."

        if ($DeviceQA) {
            Section "8b/9 Non-destructive foreground-service instrumentation QA"
            $testApk = Join-Path $ProjectRoot "android\app\build\outputs\apk\androidTest\debug\app-debug-androidTest.apk"
            if (-not (Test-Path -LiteralPath $testApk -PathType Leaf)) {
                $DeviceQaWarning = "Android-test APK was not found; device instrumentation QA was skipped."
                Warn $DeviceQaWarning
            } else {
                $testPackage = "in.diganta.aurabutler.test"
                try {
                    & $adb install -r -t $testApk | Out-Host
                    if ($LASTEXITCODE -ne 0) {
                        $DeviceQaWarning = "Could not install the separate instrumentation-test APK."
                        Warn $DeviceQaWarning
                    } else {
                        $instrumentation = @(
                            & $adb shell am instrument -w -r "$testPackage/androidx.test.runner.AndroidJUnitRunner" 2>&1
                        )
                        $instrumentation | Out-Host
                        $instrumentationText = $instrumentation -join "`n"
                        if (
                            $LASTEXITCODE -ne 0 -or
                            $instrumentationText -match "FAILURES!!!|INSTRUMENTATION_FAILED|shortMsg=Process crashed"
                        ) {
                            $DeviceQaWarning = "Foreground-service device instrumentation failed; review the output above."
                            Warn $DeviceQaWarning
                        } else {
                            Pass "Foreground-service device instrumentation"
                        }
                    }
                } finally {
                    # Remove only the separate test package. Never uninstall AURA itself,
                    # so encrypted settings, memory and owner data stay intact.
                    & $adb uninstall $testPackage 2>&1 | Out-Null
                }
            }
        }
    } else {
        Section "8/9 Device install skipped"
        if ($DeviceQA) { Warn "-DeviceQA is only run together with -Install." }
    }

    Section "9/9 Cloud source hygiene"
    $canonical = Join-Path $CloudRoot "AURA-CLOUD-CANONICAL-SOURCE.txt"
    $canonicalGeneratedAt = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $canonicalSha = Get-Sha $cloudPath
    $canonicalLines = @(
        "AURA cloud canonical source"
        "Release: v0.17.2 reliability-latency"
        ("Canonical file: " + $cloudPath)
        ("SHA256: " + $canonicalSha)
        ("Generated: " + $canonicalGeneratedAt)
        ""
    )
    $canonicalText = ($canonicalLines -join "`r`n")
    [IO.File]::WriteAllText($canonical, $canonicalText, (New-Object Text.UTF8Encoding($false)))
    Pass "Canonical cloud source marker written."

    if (-not $KeepLegacyCloudSources) {
        $legacy = New-Object System.Collections.Generic.List[System.IO.FileInfo]
        foreach ($pattern in @("aura_models_fixed.py","aura_models-BACKUP.py","aura_models.py.backup-*")) {
            foreach ($item in @(Get-ChildItem -LiteralPath $CloudRoot -Filter $pattern -File -ErrorAction SilentlyContinue)) {
                [void]$legacy.Add($item)
            }
        }
        $legacyUnique = @($legacy | Sort-Object FullName -Unique)
        if ($legacyUnique.Count -gt 0) {
            $archive = Join-Path $CloudRoot ("archive\legacy-model-sources\" + $stamp)
            New-Item -ItemType Directory -Path $archive -Force | Out-Null
            foreach ($item in $legacyUnique) {
                Move-Item -LiteralPath $item.FullName -Destination (Join-Path $archive $item.Name) -Force
            }
            Pass "Moved $($legacyUnique.Count) legacy cloud source file(s) to $archive"
        }
    } else { Warn "Legacy cloud source archive step skipped." }

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    if ($DeviceQaWarning) {
        Write-Host "SUCCESS WITH DEVICE-QA WARNING: AURA v0.17.2 applied." -ForegroundColor Yellow
    } else {
        Write-Host "SUCCESS: AURA v0.17.2 Reliability + Latency applied." -ForegroundColor Green
    }
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host "Audit:  $auditPath"
    if (-not $SkipBuild) { Write-Host "APK:    $finalDebugApk" }

    if ($VoiceUpgradeNeeded) {
        Write-Host ""
        Write-Host "IMPORTANT: Re-register Owner Voice in Settings using all 5 samples." -ForegroundColor Yellow
    } else {
        Write-Host ""
        Write-Host "Owner Voice schema v2 was already present. If you already re-enrolled after v0.17.1, no new enrollment is needed." -ForegroundColor Green
    }

    if ($CloudWarmSeconds -eq 0) {
        Write-Host "Student GPU warm window was preserved." -ForegroundColor Green
    } else {
        Write-Host "GPU warm window explicitly set to $CloudWarmSeconds seconds." -ForegroundColor Yellow
    }
}
catch {
    Write-Host ""
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
    if ($SourcePatched -and -not $ExternalSideEffectsStarted) {
        Restore-All -BackupRoot $BackupRoot -PreUpgradePresence $PreUpgradePresence -RestoreCloudConfig:($CloudWarmSeconds -ne 0)
        Write-Host "Failure occurred before cloud/device side effects, so the pre-upgrade source was restored." -ForegroundColor Green
    } elseif ($SourcePatched -and $ExternalSideEffectsStarted) {
        Write-Host "Source was not silently rolled back because a device install or cloud deployment may already have occurred." -ForegroundColor Yellow
        Write-Host "Backup: $BackupRoot" -ForegroundColor Yellow
    }
    throw
}
